contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        // record owner and balance before
        address ownerBefore = c.owner();
        uint balanceBefore = address(c).balance;
        // perform the call and record whether it reverted
        bool reverted;
        try c.go{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        // read after-values
        address ownerAfter = c.owner();
        uint balanceAfter = address(c).balance;
        // If call didn't revert then all ether held by c after the call must be 0,
        // and owner must remain the same as before. If it reverted then we make no claim about balances.
        assert(reverted || (balanceAfter == 0 && ownerAfter == ownerBefore));
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // We take an amount to forward to c.go; must ensure this contract has enough balance
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount);
        // observe owner before
        address ownerBefore = c.owner();
        // observe balances before
        uint256 cBalBefore = address(c).balance;
        uint256 meBefore = address(this).balance;
        bool reverted;
        // perform the call sending `amount` wei
        try c.go{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        // observe after-values
        address ownerAfter = c.owner();
        uint256 cBalAfter = address(c).balance;
        uint256 meAfter = address(this).balance;
        // General rule: if the call succeeded (did not revert) then owner unchanged, c.balance == 0,
        // and this contract's balance does not increase (it may decrease by `amount` if sent).
        assert(reverted || (ownerAfter == ownerBefore && cBalAfter == 0 && meAfter <= meBefore));
    }
    receive() external payable {}
}

